package api

import (
	"context"
	"encoding/base64"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/structpb"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/audit"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	auditv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/audit/v1"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	notificationsv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/notifications/v1"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

const (
	// maxLimit caps the number of rows returned by List.
	maxLimit = 50
	// defaultLimit is the default page size.
	defaultLimit = 20
	// unreadCountCap caps GetUnreadCount per spec Open Q2.
	unreadCountCap = 99
	// auditSubjectRead is the outbox subject for mark-read audit events.
	auditSubjectRead = "audit.notifications.read"
)

// NotificationsHandler implements notificationsv1.NotificationsServiceServer.
type NotificationsHandler struct {
	notificationsv1.UnimplementedNotificationsServiceServer
	pool *db.Pool
	keys audit.KeyProvider
}

// NewNotificationsHandler constructs the handler. keys may be nil only in
// read-only test setups (MarkRead/MarkAllRead return an error at runtime
// when keys is nil).
func NewNotificationsHandler(pool *db.Pool, keys audit.KeyProvider) *NotificationsHandler {
	return &NotificationsHandler{pool: pool, keys: keys}
}

// List returns a paginated list of notifications for the calling user.
// The cursor is base64(uuidv7 of last returned row); empty on the first call.
// limit defaults to 20, is clamped to 50.
func (h *NotificationsHandler) List(ctx context.Context, req *notificationsv1.ListRequest) (*notificationsv1.ListResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	recipientID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}

	limit := int32(defaultLimit)
	if req.GetLimit() > 0 {
		limit = int32(req.GetLimit())
	}
	if limit > maxLimit {
		limit = maxLimit
	}

	// Decode cursor: base64(uuidv7 string).
	var cursorID pgtype.UUID
	if c := req.GetCursor(); c != "" {
		raw, decErr := base64.StdEncoding.DecodeString(c)
		if decErr != nil {
			return nil, status.Error(codes.InvalidArgument, "invalid cursor")
		}
		parsed, parseErr := uuid.ParseBytes(raw)
		if parseErr != nil {
			return nil, status.Error(codes.InvalidArgument, "invalid cursor uuid")
		}
		cursorID = pgtype.UUID{Bytes: parsed, Valid: true}
	}

	var rows []repo.NotificationsNotification
	var unread int32

	dbErr := h.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)

		var listErr error
		rows, listErr = q.ListForRecipient(ctx, repo.ListForRecipientParams{
			RecipientUserID: recipientID,
			Column2:         cursorID,
			Limit:           limit,
		})
		if listErr != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "ListForRecipient", listErr)
		}

		unread, listErr = q.UnreadCountForRecipient(ctx, recipientID)
		if listErr != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "UnreadCountForRecipient", listErr)
		}
		return nil
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}

	// Cap unread at 99.
	if unread > unreadCountCap {
		unread = unreadCountCap
	}

	out := &notificationsv1.ListResponse{
		Notifications: make([]*notificationsv1.Notification, 0, len(rows)),
		UnreadCount:   uint32(unread),
	}
	for i := range rows {
		out.Notifications = append(out.Notifications, rowToProto(&rows[i]))
	}

	// Set next_cursor to base64 of last row's ID when there are results.
	if len(rows) > 0 {
		lastID := rows[len(rows)-1].ID
		out.NextCursor = base64.StdEncoding.EncodeToString([]byte(lastID.String()))
	}

	return out, nil
}

// GetUnreadCount returns the number of unread notifications for the calling
// user, capped at 99 per spec.
func (h *NotificationsHandler) GetUnreadCount(ctx context.Context, _ *notificationsv1.GetUnreadCountRequest) (*notificationsv1.GetUnreadCountResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	recipientID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}

	var count int32
	dbErr := h.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)
		var qErr error
		count, qErr = q.UnreadCountForRecipient(ctx, recipientID)
		return qErr
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}
	if count > unreadCountCap {
		count = unreadCountCap
	}
	return &notificationsv1.GetUnreadCountResponse{Count: uint32(count)}, nil
}

// MarkRead marks a single notification as read. Returns NotFound both when
// the row does not exist at all and when it belongs to another recipient in
// the same org — the two cases are made indistinguishable (same code, same
// message, no extra probe) so a caller cannot use this endpoint to enumerate
// other members' notification existence within the org. Cross-org guesses
// already return NotFound because the query runs inside the RLS-scoped
// transaction.
func (h *NotificationsHandler) MarkRead(ctx context.Context, req *notificationsv1.MarkReadRequest) (*notificationsv1.MarkReadResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	recipientID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "id required")
	}
	notifID, err := uuid.Parse(req.GetId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid notification id")
	}

	dbErr := h.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)

		// MarkOneRead only affects rows where recipient_user_id matches the
		// caller AND read_at IS NULL. 0 rows affected → either already read
		// (idempotent OK), or row belongs to someone else, or row does not exist.
		affected, markErr := q.MarkOneRead(ctx, repo.MarkOneReadParams{
			ID:              notifID,
			RecipientUserID: recipientID,
		})
		if markErr != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "MarkOneRead", markErr)
		}
		if affected == 0 {
			// 0 rows affected means one of:
			//   (a) the row does not exist for any recipient in this org
			//   (b) the row exists but belongs to another recipient in this org
			//   (c) the row exists, belongs to the caller, and is already read (idempotent)
			// A single probe (scoped by RLS to this org) distinguishes (c) from
			// (a)/(b). (a) and (b) collapse to the same NotFound response —
			// they must be indistinguishable to callers, so no separate
			// existence check is made.
			var existingReadAt pgtype.Timestamptz
			var rowRecipient uuid.UUID
			scanErr := tx.QueryRow(ctx,
				`SELECT read_at, recipient_user_id FROM notifications.notification WHERE id = $1`,
				notifID,
			).Scan(&existingReadAt, &rowRecipient)
			if errors.Is(scanErr, pgx.ErrNoRows) || (scanErr == nil && rowRecipient != recipientID) {
				return observability.New(observability.CodeNotFound, "notification not found")
			}
			if scanErr != nil {
				return observability.Wrap(observability.CodeServiceUnavailable, "check notification state", scanErr)
			}
			// Row exists, belongs to the caller, and is already read — treat
			// as idempotent success. We didn't change state, so no audit entry.
			return nil
		}

		// Emit audit entry for the state change.
		return h.emitMarkReadAudit(ctx, tx, notifID, recipientID, hdrs, 1)
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}
	return &notificationsv1.MarkReadResponse{}, nil
}

// MarkAllRead marks all unread notifications for the calling user as read.
// Returns the number of rows affected.
func (h *NotificationsHandler) MarkAllRead(ctx context.Context, _ *notificationsv1.MarkAllReadRequest) (*notificationsv1.MarkAllReadResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	recipientID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}

	var affected int64
	dbErr := h.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)
		var markErr error
		affected, markErr = q.MarkAllReadForRecipient(ctx, recipientID)
		if markErr != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "MarkAllReadForRecipient", markErr)
		}
		if affected == 0 {
			// No unread rows — idempotent, skip audit.
			return nil
		}
		return h.emitMarkReadAudit(ctx, tx, uuid.Nil, recipientID, hdrs, affected)
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}
	return &notificationsv1.MarkAllReadResponse{Affected: uint32(affected)}, nil
}

// emitMarkReadAudit writes an audit.notifications.read entry to the outbox
// in the same transaction as the state change. For MarkRead, notifID is the
// specific notification; for MarkAllRead, notifID is uuid.Nil (rollup).
func (h *NotificationsHandler) emitMarkReadAudit(
	ctx context.Context,
	tx pgx.Tx,
	notifID uuid.UUID,
	recipientID uuid.UUID,
	hdrs auth.Headers,
	affected int64,
) error {
	if h.keys == nil {
		return observability.New(observability.CodeInternal, "audit emission requires KeyProvider")
	}

	eventID, err := uuid.NewV7()
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "uuid.NewV7 for audit event", err)
	}

	payloadFields := map[string]any{
		"recipient_user_id": recipientID.String(),
		"affected":          affected,
	}
	if notifID != uuid.Nil {
		payloadFields["notification_id"] = notifID.String()
	}

	payload, err := structpb.NewStruct(payloadFields)
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "build audit payload", err)
	}

	event := &auditv1.AuditEvent{
		EventId:       eventID.String(),
		EmittedAt:     timestamppb.New(time.Now()),
		SourceService: "notifications-svc",
		Action:        "notifications.notification.read",
		TargetType:    "notification",
		TargetId:      notifID.String(),
		Payload:       payload,
	}
	if hdrs.TenantID != "" {
		if tenantUUID, parseErr := uuid.Parse(hdrs.TenantID); parseErr == nil {
			event.ActorOrg = &commonv1.OrgID{Value: tenantUUID.String()}
		}
	}
	if hdrs.UserID != "" {
		event.Actor = &auditv1.AuditEvent_ActorUser{
			ActorUser: &commonv1.UserID{Value: hdrs.UserID},
		}
	}
	if hdrs.RequestID != "" {
		event.RequestId = &commonv1.RequestID{Value: hdrs.RequestID}
	}

	prev, err := h.lastRowHash(ctx, tx)
	if err != nil {
		return err
	}
	keyID, key := h.keys.ActiveKey()
	if err := audit.ChainEvent(event, prev, keyID, key); err != nil {
		return observability.Wrap(observability.CodeInternal, "audit.ChainEvent", err)
	}

	// Write directly to audit_chain table (not via outbox, since this
	// service writes its own audit chain to its own schema).
	return h.insertAuditChain(ctx, tx, hdrs, recipientID, event)
}

// insertAuditChain persists the audit event into notifications.audit_chain
// in the same transaction.
func (h *NotificationsHandler) insertAuditChain(
	ctx context.Context,
	tx pgx.Tx,
	hdrs auth.Headers,
	actorID uuid.UUID,
	event *auditv1.AuditEvent,
) error {
	payload, err := proto.Marshal(event)
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "marshal audit event", err)
	}

	var dbActorID pgtype.UUID
	if actorID != uuid.Nil {
		dbActorID = pgtype.UUID{Bytes: actorID, Valid: true}
	}

	var orgID pgtype.UUID
	if hdrs.TenantID != "" {
		if tenantUUID, parseErr := uuid.Parse(hdrs.TenantID); parseErr == nil {
			orgID = pgtype.UUID{Bytes: tenantUUID, Valid: true}
		}
	}

	prevHashBytes := []byte(event.PrevRowHash)
	entryHashBytes := []byte(event.RowHash)

	_, err = tx.Exec(ctx,
		`INSERT INTO notifications.audit_chain
		  (org_id, actor_id, action, payload, prev_hash, entry_hash)
		 VALUES ($1, $2, $3, $4, $5, $6)`,
		orgID,
		dbActorID,
		event.Action,
		payload,
		prevHashBytes,
		entryHashBytes,
	)
	return err
}

// lastRowHash returns the row_hash of the most recent audit_chain row
// within the caller's tenant scope. Returns "" for the genesis row.
func (h *NotificationsHandler) lastRowHash(ctx context.Context, tx pgx.Tx) (string, error) {
	if tx == nil {
		return "", nil
	}
	var rawPayload []byte
	err := tx.QueryRow(ctx,
		`SELECT payload FROM notifications.audit_chain ORDER BY seq DESC LIMIT 1 FOR UPDATE`,
	).Scan(&rawPayload)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return "", nil
		}
		return "", observability.Wrap(observability.CodeInternal, "lastRowHash query", err)
	}
	var prev auditv1.AuditEvent
	if err := proto.Unmarshal(rawPayload, &prev); err != nil {
		return "", observability.Wrap(observability.CodeInternal, "lastRowHash unmarshal", err)
	}
	return prev.RowHash, nil
}

// rowToProto converts a repo notification row to the proto message.
func rowToProto(r *repo.NotificationsNotification) *notificationsv1.Notification {
	n := &notificationsv1.Notification{
		Id:            r.ID.String(),
		Kind:          kindToProto(r.Kind),
		Title:         r.Title,
		Snippet:       r.Snippet,
		Monogram:      r.Monogram,
		MonogramBg:    r.MonogramBg,
		SourceEventId: r.SourceEventID.String(),
		TargetId:      derefStr(r.TargetID),
	}
	if r.CreatedAt.Valid {
		n.CreatedAt = timestamppb.New(r.CreatedAt.Time)
	}
	if r.ReadAt.Valid {
		n.ReadAt = timestamppb.New(r.ReadAt.Time)
	}
	return n
}

// derefStr returns the pointed-to string, or "" when nil.
func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func kindToProto(k repo.NotificationsNotificationKind) notificationsv1.NotificationKind {
	switch k {
	case repo.NotificationsNotificationKindInviteAccepted:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED
	case repo.NotificationsNotificationKindMembershipAdded:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED
	case repo.NotificationsNotificationKindWorkspaceSwitched:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED
	case repo.NotificationsNotificationKindIngestCompleted:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED
	case repo.NotificationsNotificationKindIngestFailed:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED
	case repo.NotificationsNotificationKindRoleChanged:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED
	case repo.NotificationsNotificationKindLoginNewDevice:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE
	case repo.NotificationsNotificationKindMessageReceived:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_MESSAGE_RECEIVED
	default:
		return notificationsv1.NotificationKind_NOTIFICATION_KIND_UNSPECIFIED
	}
}

// mapError converts an observability.Error to a gRPC status error.
func mapError(err error) error {
	switch {
	case observability.IsCode(err, observability.CodeNotFound):
		return status.Error(codes.NotFound, err.Error())
	case observability.IsCode(err, observability.CodeForbidden):
		return status.Error(codes.PermissionDenied, err.Error())
	case observability.IsCode(err, observability.CodeValidationFailed):
		return status.Error(codes.InvalidArgument, err.Error())
	case observability.IsCode(err, observability.CodeServiceUnavailable):
		return status.Error(codes.Unavailable, err.Error())
	default:
		return status.Error(codes.Internal, err.Error())
	}
}


