// testAuditKeys returns a minimal audit.KeyProvider for tests.
// AUDIT_HMAC_KEYS format: "keyid:base64key" (comma-separated for multiple keys).
func testAuditKeys(t *testing.T) audit.KeyProvider {
	t.Helper()
	// 32-byte key: "test-hmac-key-32-bytes-padded!!" base64-encoded.
	p, err := audit.NewEnvKeyProvider("test-key-1:dGVzdC1obWFjLWtleS0zMi1ieXRlcy1wYWRkZWQh", "test-key-1")
	require.NoError(t, err)
	return p
}

// isReadAt checks if the notification row with the given ID has a non-null read_at.
func isReadAt(t *testing.T, pool *platformdb.Pool, orgID, notifID uuid.UUID) bool {
	t.Helper()
	var readAtNull sql.NullTime
	ctx := auth.HeadersIntoContext(context.Background(), auth.Headers{TenantID: orgID.String()})
	err := pool.WithTx(ctx, func(tx pgx.Tx) error {
		return tx.QueryRow(ctx,
			`SELECT read_at FROM notifications.notification WHERE id = $1`,
			notifID,
		).Scan(&readAtNull)
	})
	require.NoError(t, err)
	return readAtNull.Valid
}

