	_, err := h.MarkRead(ctx, &notificationsv1.MarkReadRequest{Id: notifID.String()})
	require.Error(t, err)
	st, ok := status.FromError(err)
	require.True(t, ok)
	assert.Equal(t, codes.NotFound, st.Code(), "should return NotFound for wrong recipient, not PermissionDenied")

	// Message must be identical to the nonexistent-UUID case — no
	// distinguishable signal that the row exists for someone else.
	ctx2 := handlerCtx(orgID, otherUser)
	_, err2 := h.MarkRead(ctx2, &notificationsv1.MarkReadRequest{Id: uuid.New().String()})
	require.Error(t, err2)
	st2, ok := status.FromError(err2)
	require.True(t, ok)
	assert.Equal(t, codes.NotFound, st2.Code())
	assert.Equal(t, st2.Message(), st.Message(), "wrong-recipient and nonexistent-UUID must be indistinguishable")
}

