package api

import (
	"context"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	notificationsv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/notifications/v1"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

// allKnownKinds returns the 7 concrete NotificationKind values in a stable
// canonical order. UNSPECIFIED is intentionally excluded — it is not a valid
// user-facing preference.
func allKnownKinds() []notificationsv1.NotificationKind {
	return []notificationsv1.NotificationKind{
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE,
	}
}

// protoKindToRepo maps from the proto enum to the sqlc-generated repo enum.
func protoKindToRepo(k notificationsv1.NotificationKind) repo.NotificationsNotificationKind {
	switch k {
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED:
		return repo.NotificationsNotificationKindInviteAccepted
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED:
		return repo.NotificationsNotificationKindMembershipAdded
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED:
		return repo.NotificationsNotificationKindWorkspaceSwitched
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED:
		return repo.NotificationsNotificationKindIngestCompleted
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED:
		return repo.NotificationsNotificationKindIngestFailed
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED:
		return repo.NotificationsNotificationKindRoleChanged
	case notificationsv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE:
		return repo.NotificationsNotificationKindLoginNewDevice
	default:
		return ""
	}
}

// repoKindToProtoPrefs maps the repo enum to the proto enum for preference
// responses. Distinct from kindToProto in handler.go to avoid a naming
// collision; they do the same mapping.
func repoKindToProtoPrefs(k repo.NotificationsNotificationKind) notificationsv1.NotificationKind {
	return kindToProto(k)
}

// GetNotificationPreferencesSelf returns the caller's per-kind in-app
// notification preferences. Missing kinds default to enabled=true.
func (h *NotificationsHandler) GetNotificationPreferencesSelf(
	ctx context.Context,
	_ *notificationsv1.GetNotificationPreferencesSelfRequest,
) (*notificationsv1.GetNotificationPreferencesSelfResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	userID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}
	if hdrs.TenantID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-tenant-id header required")
	}
	orgID, err := uuid.Parse(hdrs.TenantID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-tenant-id header")
	}

	// Build the default map: all kinds enabled.
	enabled := make(map[notificationsv1.NotificationKind]bool, 7)
	for _, k := range allKnownKinds() {
		enabled[k] = true
	}

	dbErr := h.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)
		rows, qErr := q.GetUserKindPreferences(ctx, repo.GetUserKindPreferencesParams{
			OrgID:  pgtype.UUID{Bytes: orgID, Valid: true},
			UserID: pgtype.UUID{Bytes: userID, Valid: true},
		})
		if qErr != nil {
			return qErr
		}
		// Override defaults with stored values.
		for _, r := range rows {
			protoKind := repoKindToProtoPrefs(r.Kind)
			if protoKind != notificationsv1.NotificationKind_NOTIFICATION_KIND_UNSPECIFIED {
				enabled[protoKind] = r.Enabled
			}
		}
		return nil
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}

	out := make([]*notificationsv1.NotificationKindPreference, 0, len(enabled))
	for _, k := range allKnownKinds() {
		out = append(out, &notificationsv1.NotificationKindPreference{
			Kind:    k,
			Enabled: enabled[k],
		})
	}
	return &notificationsv1.GetNotificationPreferencesSelfResponse{Preferences: out}, nil
}

// SetNotificationPreferencesSelf writes the full set of per-kind preferences
// for the caller. The request must contain all 7 known kinds; partial
// submissions are rejected with InvalidArgument.
//
// TODO: wrap in a single tx with audit emission for
// audit.notifications.user_preferences_updated once the notifications-svc
// audit pattern is established for preference mutations.
func (h *NotificationsHandler) SetNotificationPreferencesSelf(
	ctx context.Context,
	req *notificationsv1.SetNotificationPreferencesSelfRequest,
) (*notificationsv1.SetNotificationPreferencesSelfResponse, error) {
	hdrs := auth.HeadersFromContext(ctx)
	if hdrs.UserID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-user-id header required")
	}
	userID, err := uuid.Parse(hdrs.UserID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-user-id header")
	}
	if hdrs.TenantID == "" {
		return nil, status.Error(codes.Unauthenticated, "x-tenant-id header required")
	}
	orgID, err := uuid.Parse(hdrs.TenantID)
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid x-tenant-id header")
	}

	// Validate: no UNSPECIFIED, no duplicates.
	seen := make(map[notificationsv1.NotificationKind]bool, len(req.GetPreferences()))
	for _, p := range req.GetPreferences() {
		if p.GetKind() == notificationsv1.NotificationKind_NOTIFICATION_KIND_UNSPECIFIED {
			return nil, status.Error(codes.InvalidArgument, "UNSPECIFIED kind not allowed")
		}
		if seen[p.GetKind()] {
			return nil, status.Errorf(codes.InvalidArgument, "duplicate kind: %s", p.GetKind())
		}
		seen[p.GetKind()] = true
	}
	// Validate: all 7 known kinds must be present.
	for _, k := range allKnownKinds() {
		if !seen[k] {
			return nil, status.Errorf(codes.InvalidArgument, "missing kind: %s", k)
		}
	}

	// Upsert each preference row.
	dbErr := h.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)
		for _, p := range req.GetPreferences() {
			if upsertErr := q.UpsertUserKindPreference(ctx, repo.UpsertUserKindPreferenceParams{
				OrgID:   pgtype.UUID{Bytes: orgID, Valid: true},
				UserID:  pgtype.UUID{Bytes: userID, Valid: true},
				Kind:    protoKindToRepo(p.GetKind()),
				Enabled: p.GetEnabled(),
			}); upsertErr != nil {
				return upsertErr
			}
		}
		return nil
	})
	if dbErr != nil {
		return nil, mapError(dbErr)
	}

	// Read back + return.
	getResp, err := h.GetNotificationPreferencesSelf(ctx, &notificationsv1.GetNotificationPreferencesSelfRequest{})
	if err != nil {
		return nil, err
	}
	return &notificationsv1.SetNotificationPreferencesSelfResponse{
		Preferences: getResp.GetPreferences(),
	}, nil
}


