// TestRowToProto_MessageReceived_MapsKindAndTargetID verifies that rowToProto
// correctly maps the MESSAGE_RECEIVED kind and surfaces TargetID.
func TestRowToProto_MessageReceived_MapsKindAndTargetID(t *testing.T) {
	cid := "018f6e2a-0000-7000-8000-0000000000c0"
	row := &repo.NotificationsNotification{
		ID:            uuid.New(),
		Kind:          repo.NotificationsNotificationKindMessageReceived,
		Title:         "Alice",
		SourceEventID: uuid.New(),
		TargetID:      &cid,
	}
	got := rowToProto(row)
	require.Equal(t, notificationsv1.NotificationKind_NOTIFICATION_KIND_MESSAGE_RECEIVED, got.GetKind())
	require.Equal(t, cid, got.GetTargetId())
}

// TestRowToProto_NilTargetID_EmptyString verifies that rowToProto emits an
// empty TargetId string when row.TargetID is nil.
func TestRowToProto_NilTargetID_EmptyString(t *testing.T) {
	row := &repo.NotificationsNotification{
		ID:            uuid.New(),
		Kind:          repo.NotificationsNotificationKindInviteAccepted,
		Title:         "Bob accepted your invite",
		SourceEventID: uuid.New(),
		TargetID:      nil,
	}
	got := rowToProto(row)
	require.Equal(t, "", got.GetTargetId())
