// startAPITestPostgres spins up a Postgres testcontainer and returns an app-role pool.
func startAPITestPostgres(t *testing.T) (*platformdb.Pool, string, func()) {
	t.Helper()
	ctx := context.Background()

	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("notifications_api_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)

	adminDSN, err := pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	_, file, _, _ := runtime.Caller(0)
	migrationsDir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")

	goose.SetTableName("goose_db_version_notifications")
	require.NoError(t, goose.SetDialect("postgres"))
	gooseDB, err := goose.OpenDBWithDriver("pgx", adminDSN)
	require.NoError(t, err)
	require.NoError(t, goose.Up(gooseDB, migrationsDir))

	_, err = gooseDB.Exec(`
		DO $$ BEGIN
			IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'notifications_app') THEN
				CREATE ROLE notifications_app NOLOGIN NOBYPASSRLS;
			END IF;
		END $$`)
	require.NoError(t, err)
	_, err = gooseDB.Exec(`ALTER ROLE notifications_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	_, err = gooseDB.Exec(`GRANT USAGE ON SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)
	_, err = gooseDB.Exec(`GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)
	_, err = gooseDB.Exec(`GRANT USAGE ON ALL SEQUENCES IN SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)
	require.NoError(t, gooseDB.Close())

	u, _ := url.Parse(adminDSN)
	u.User = url.UserPassword("notifications_app", "test_app")
	appDSN := u.String()

	pool, err := platformdb.NewPool(ctx, appDSN)
	require.NoError(t, err)

	cleanup := func() {
		pool.Close()
		_ = pgC.Terminate(ctx)
	}
	return pool, adminDSN, cleanup
}

// seedNotification inserts a notification row via raw SQL (bypasses RLS).
func seedNotification(t *testing.T, pool *platformdb.Pool, orgID, recipientID uuid.UUID, title string) uuid.UUID {
	t.Helper()
	id, err := uuid.NewV7()
	require.NoError(t, err)
	sourceEventID := uuid.New()
	natsMsgID := fmt.Sprintf("test-%s", id.String())

	ctx := auth.HeadersIntoContext(context.Background(), auth.Headers{
		TenantID: orgID.String(),
		UserID:   recipientID.String(),
	})
	err = pool.WithTx(ctx, func(tx pgx.Tx) error {
		_, txErr := tx.Exec(ctx,
			`INSERT INTO notifications.notification
			  (id, org_id, recipient_user_id, kind, title, snippet, monogram, monogram_bg, source_event_id, nats_msg_id)
			 VALUES ($1, $2, $3, 'invite_accepted', $4, 'Snippet', 'A', '#1A4FD6', $5, $6)`,
			id, orgID, recipientID, title, sourceEventID, natsMsgID,
		)
