func testAuditKeys(t *testing.T) audit.KeyProvider {
	t.Helper()
	// 32-byte key: "test-hmac-key-32-bytes-padded!!" base64-encoded.
	p, err := audit.NewEnvKeyProvider("test-key-1:dGVzdC1obWFjLWtleS0zMi1ieXRlcy1wYWRkZWQh", "test-key-1")
	require.NoError(t, err)
	return p
}

// isReadAt checks if the notification row with the given ID has a non-null read_at.
func isReadAt(t *testing.T, pool *platformdb.Pool, orgID, notifID uuid.UUID) bool {
	t.Helper()
