// buildAllPrefs builds a map of all 7 kinds defaulting to enabled=true.
func buildAllPrefs(_ *testing.T) map[notificationsv1.NotificationKind]bool {
	return map[notificationsv1.NotificationKind]bool{
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED:    true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED:   true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED: true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED:   true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED:      true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED:       true,
		notificationsv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE:   true,
	}
}

// buildSetRequest converts a kind→enabled map to a SetNotificationPreferencesSelfRequest.
func buildSetRequest(prefs map[notificationsv1.NotificationKind]bool) *notificationsv1.SetNotificationPreferencesSelfRequest {
	req := &notificationsv1.SetNotificationPreferencesSelfRequest{}
	for k, v := range prefs {
		req.Preferences = append(req.Preferences, &notificationsv1.NotificationKindPreference{
			Kind:    k,
			Enabled: v,
		})
	}
	return req
}


